  if (std::forward_iterator<InputIterator> && std::next(first) == last) {
    insert(end(), *first);
    return;
  }



  auto middle = [this, size = size()] {
    return std::next(begin(), static_cast<difference_type>(size));
  };


  auto pos_first_new = static_cast<difference_type>(size());



