static inline int32_t PerfettoPbZigZagDecode32(uint32_t value) {
  uint32_t mask =
      static_cast<uint32_t>(-static_cast<int32_t>(value & 1));
  return static_cast<int32_t>(((value >> 1) ^ mask));
}

