class __attribute__((capability("mutex"))) SkMutex {
public:
    constexpr SkMutex() = default;

    ~SkMutex() {
        this->assertNotHeld();
    }

    void acquire() __attribute__((acquire_capability())) {
        fSemaphore.wait();

    }

    void release() __attribute__((release_capability())) {
        this->assertHeld();

        fSemaphore.signal();
    }

    void assertHeld() __attribute__((assert_capability(this))) {
        static_cast<void>(0);
    }

    void assertNotHeld() {
        static_cast<void>(0);
    }

private:
    SkSemaphore fSemaphore{1};

};

